std::uint16_t dwgCalcCrc16(std::uint16_t seed, const std::uint8_t* data, std::size_t len)
{
    std::uint16_t dx = seed;
    for (std::size_t i = 0; i < len; ++i) {
        const std::uint8_t al = static_cast<std::uint8_t>(data[i] ^ (dx & 0xFF));
        dx = static_cast<std::uint16_t>(((dx >> 8) & 0xFF) ^ kCrcTable[al]);
    }
    return dx;
}

std::uint16_t dwgBitWriter::crc16(std::uint16_t dx, std::size_t start, std::size_t end) const
{
    if (start >= end || end > buf.size()) return 0;
    return dwgCalcCrc16(dx, buf.data() + start, end - start);
}

// -----------------------------------------------------------------------------
//  哨兵
// -----------------------------------------------------------------------------
namespace {
enum SentinelKind {
    kSentHeaderEnd = 0,     // header 节（起止同用 VARIABLE 组：实测文件头节
    kSentThumbnailBegin,    //   以 VARIABLE_BEGIN 开头、VARIABLE_END 结尾）
    kSentThumbnailEnd,
    kSentVariableBegin,
    kSentVariableEnd,
    kSentClassBegin,
    kSentClassEnd,
    kSent2ndHeaderBegin,
    kSent2ndHeaderEnd
};
}

void dwgSentinelBytes(int kind, bool begin, std::uint8_t out[16])
{
    // 注：header 数据节使用 VARIABLE 组（BEGIN/END 互补）；
    //     classes 节使用 CLASS 组；缩略图使用 THUMBNAIL 组。
    static const std::uint8_t kSentinels[][16] = {
        { 0x95, 0xA0, 0x4E, 0x28, 0x99, 0x82, 0x1A, 0xE5,
          0x5E, 0x41, 0xE0, 0x5F, 0x9D, 0x3A, 0x4D, 0x00 },   // HEADER_END
        { 0x1F, 0x25, 0x6D, 0x07, 0xD4, 0x36, 0x28, 0x28,
          0x9D, 0x57, 0xCA, 0x3F, 0x9D, 0x44, 0x10, 0x2B },   // THUMBNAIL_BEGIN
        { 0xE0, 0xDA, 0x92, 0xF8, 0x2B, 0xC9, 0xD7, 0xD7,
          0x62, 0xA8, 0x35, 0xC0, 0x62, 0xBB, 0xEF, 0xD4 },   // THUMBNAIL_END
        { 0xCF, 0x7B, 0x1F, 0x23, 0xFD, 0xDE, 0x38, 0xA9,
          0x5F, 0x7C, 0x68, 0xB8, 0x4E, 0x6D, 0x33, 0x5F },   // VARIABLE_BEGIN
        { 0x30, 0x84, 0xE0, 0xDC, 0x02, 0x21, 0xC7, 0x56,
          0xA0, 0x83, 0x97, 0x47, 0xB1, 0x92, 0xCC, 0xA0 },   // VARIABLE_END
        { 0x8D, 0xA1, 0xC4, 0xB8, 0xC4, 0xA9, 0xF8, 0xC5,
          0xC0, 0xDC, 0xF4, 0x5F, 0xE7, 0xCF, 0xB6, 0x8A },   // CLASS_BEGIN
        { 0x72, 0x5E, 0x3B, 0x47, 0x3B, 0x56, 0x07, 0x3A,
          0x3F, 0x23, 0x0B, 0xA0, 0x18, 0x30, 0x49, 0x75 },   // CLASS_END
        { 0xD4, 0x7B, 0x21, 0xCE, 0x28, 0x93, 0x9F, 0xBF,
          0x53, 0x24, 0x40, 0x09, 0x12, 0x3C, 0xAA, 0x01 },   // 2NDHEADER_BEGIN
        { 0x2B, 0x84, 0xDE, 0x31, 0xD7, 0x6C, 0x60, 0x40,
          0xAC, 0xDB, 0xBF, 0xF6, 0xED, 0xC3, 0x55, 0xFE }    // 2NDHEADER_END
    };
    const std::uint8_t* base = kSentinels[kind];
    for (int i = 0; i < 16; ++i)
        out[i] = begin ? base[i] : static_cast<std::uint8_t>(~base[i]);
}

// -----------------------------------------------------------------------------
//  文本
// -----------------------------------------------------------------------------
void dwgBitWriter::writeT(const std::string& utf8, DRW_TextCodec& codec)
{
    const std::string encoded = codec.fromUtf8(utf8);
    writeBS(static_cast<dint16>(encoded.size()));
    for (unsigned char c : encoded)
        writeRC(static_cast<std::uint8_t>(c));
}
